import{_ as e,o as s,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Students and guardians","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/eleves-tuteurs.md","filePath":"src/en/guide/admin/eleves-tuteurs.md"}'),r={name:"en/guide/admin/eleves-tuteurs.md"};function o(i,t,l,d,c,h){return s(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="students-and-guardians" tabindex="-1">Students and guardians <a class="header-anchor" href="#students-and-guardians" aria-label="Permalink to &quot;Students and guardians&quot;">​</a></h1><p>This section covers a student&#39;s record and everything attached to it: their class enrollment, their guardians (parents), their possible personal access to the student portal, and their specialty subjects.</p><h2 id="student-records" tabindex="-1">Student records <a class="header-anchor" href="#student-records" aria-label="Permalink to &quot;Student records&quot;">​</a></h2><p><strong>Students &amp; admissions → Students</strong> lists the school&#39;s students, with a search by name and a filter by class (including &quot;Unassigned&quot; for students with no class in the current year).</p><p>Click a student&#39;s row to open their <strong>preview</strong>, to the right of the list on a large screen, or at the bottom of the screen on a phone. Without leaving the list, it gathers: the class and site, the linked parents or guardians with their email address, the year&#39;s fees (total paid and balance), attendance (absences, unjustified absences, lates) and the last three grades. Three buttons lead straight on: <strong>Edit</strong>, <strong>Parents / guardians</strong> and <strong>Billing</strong>.</p><p>To create a student:</p><ol><li>Click <strong>New student</strong>.</li><li>Fill in the <strong>First name</strong>, <strong>Last name</strong>, and <strong>Date of birth</strong> (optional).</li><li>Choose a <strong>Class</strong> for the current academic year, or leave it unassigned to create the record without an immediate enrollment.</li><li>Click <strong>Save</strong>.</li></ol><p>Editing a student shows the same fields, with one difference for the class. A student with <strong>no class</strong> this academic year can be enrolled directly. An <strong>already enrolled</strong> student shows their class with a <strong>Change class</strong> button: moving them goes through a <a href="/era-guide/en/guide/secretariat/changements-de-classe.html">class change</a>, which checks the site and capacity and records the reason. The form never takes a student out of their class, since their enrollment carries their payments and bulletins.</p><p>The record also shows two read-only tables if the student has history:</p><ul><li><strong>Enrollment history</strong> — the classes attended in previous academic years.</li><li><strong>Curriculum history</strong> — every move of the student from one class to another during a year (class change, site transfer), with the date, who made it, and each class&#39;s department and site — so a change of pedagogical curriculum (French ↔ Togolese) shows there too.</li></ul><p>From a student&#39;s record, three buttons open dedicated screens: <strong>Specialty subjects</strong>, <strong>Guardians</strong>, and <strong>Student account</strong> (detailed below).</p><h2 id="guardians-parents" tabindex="-1">Guardians (parents) <a class="header-anchor" href="#guardians-parents" aria-label="Permalink to &quot;Guardians (parents)&quot;">​</a></h2><p>From a student&#39;s record, click <strong>Guardians</strong> to manage who has parent portal access for this student.</p><p>To add a guardian:</p><ol><li>Click <strong>Add guardian</strong>.</li><li>Fill in the <strong>Name</strong>, <strong>Email</strong>, <strong>Relationship</strong> (Father, Mother, Legal guardian, or Other), and check <strong>Primary contact</strong> if they&#39;re the main point of contact.</li><li>Repeat for each additional guardian (<strong>Remove</strong> button to drop one from the form).</li><li>Click <strong>Save changes</strong>.</li></ol><p>Each guardian attached this way gets parent portal access to this student and to any other student they&#39;re linked to elsewhere.</p><h2 id="student-account-student-portal" tabindex="-1">Student account (student portal) <a class="header-anchor" href="#student-account-student-portal" aria-label="Permalink to &quot;Student account (student portal)&quot;">​</a></h2><p>From a student&#39;s record, click <strong>Student account</strong>. Personal access to the student portal is only possible for a student enrolled in high school or above — for others, the page shows an ineligibility message and nothing else.</p><p>For an eligible student:</p><ul><li><strong>Create account</strong> — enter an email address and click <strong>Create account</strong>; the student can then sign in with it.</li><li><strong>Update email</strong> — if an account already exists, change the address and click <strong>Update email</strong>.</li><li><strong>Revoke access</strong> — removes the student&#39;s personal access without touching their record.</li></ul><h2 id="specialty-subjects" tabindex="-1">Specialty subjects <a class="header-anchor" href="#specialty-subjects" aria-label="Permalink to &quot;Specialty subjects&quot;">​</a></h2><p>From a student&#39;s record, click <strong>Specialty subjects</strong>. This screen only shows something if the student has an active enrollment and their department has subjects marked &quot;specialty&quot; (see <a href="/era-guide/en/guide/admin/structure-etablissement.html">School structure</a>).</p><p>For each specialty subject offered:</p><ol><li>Check the box to select it for this student.</li><li>Optionally fill in a personal <strong>coefficient</strong> that replaces the department&#39;s default — otherwise the department&#39;s default coefficient applies.</li><li>Click <strong>Save changes</strong>.</li></ol>',24)])])}const p=e(r,[["render",o]]);export{g as __pageData,p as default};
